{"description":"Extract all symbolic_call events with target and SQL from dumps","command":"python3 -c "
import json, os, glob
from collections import defaultdict

dumps_dir = '/work/in/packet/dumps/'
target_calls = defaultdict(list)

for fpath in sorted(glob.glob(os.path.join(dumps_dir, '*.json'))):
    with open(fpath) as f:
        d = json.load(f)
    for event in d.get('events', []):
        if event.get('kind') == 'symbolic_call':
            target = event.get('target', '?')
            notes = event.get('notes', [])
            note_text = ''
            if notes and isinstance(notes, list) and len(notes) > 0:
                n = notes[0]
                if isinstance(n, dict):
                    note_text = n.get('text', str(n))
                else:
                    note_text = str(n)
            target_calls[target].append((os.path.basename(fpath), note_text[:300]))

for target, calls in sorted(target_calls.items()):
    print(f'=== {target} ({len(calls)} calls) ===')
    for fname, note in calls[:3]:
        print(f'  [{fname}] {note[:200]}')
    if len(calls) > 3:
        print(f'  ... and {len(calls)-3} more')
    print()
" 2>&1"}

