{"description":"Check note field types across all dumps","command":"python3 -c "
import json, os, glob
from collections import Counter

dumps_dir = '/work/in/packet/dumps/'
note_types = Counter()

for fpath in sorted(glob.glob(os.path.join(dumps_dir, '*.json'))):
    with open(fpath) as f:
        d = json.load(f)
    for event in d.get('events', []):
        if event.get('type') == 'symbolic_call':
            note = event.get('note', None)
            note_types[type(note).__name__ + ('/empty' if not note else '')] += 1

for t, c in note_types.most_common():
    print(f'  {t}: {c}')
" 2>&1"}

